35	// DEVDESK-341 step 3: the footer's activity dot, guarded and accepted at the
36	// router. The seeds below put a view on screen with jobs work running and the
37	// cursor on an IDLE row (or on none), so no row detail carries a glyph and the
38	// footer must carry its own dot.
39	
40	// renderedFrameName is the router's styled braille frame, which no footer reads
41	// and which jobs.FrameMsg no longer carries (retired in step 5).
42	const renderedFrameName = "RenderedFrame"
43	
44	// footerSeed puts a view on screen, jobs work running and no selected row busy.
45	type footerSeed func(*testing.T, *App)
46	
47	// footerActivitySeeds are the seven views whose footer shows the shared activity
48	// dot (the router-driven sites of DEVDESK-341). Every one is checked for braille
49	// and for exactly one running glyph.
50	var footerActivitySeeds = map[command.ViewType]footerSeed{
51		command.ViewDashboard:    seedDashboardActivity,
52		command.ViewJobs:         seedJobsActivity,
53		command.ViewWorkspaces:   seedWorkspacesActivity,
54		command.ViewTemplates:    seedTemplatesActivity,
55		command.ViewSecurity:     seedSecurityActivity,
56		command.ViewOCIResources: seedOCIActivity,
57		command.ViewGitExplorer:  seedExplorerActivity,
58	}
59	
60	// loadingSeed is one loading state of a view and the message that ends it.
61	type loadingSeed struct {
62		name string // subtest name
63		seed footerSeed
64		end  func() tea.Msg
65	}
66	
67	// footerLoadingSeeds are the views whose footer shows the activity dot for a
68	// load of their own, with no job in the registry (DEVDESK-369): the view is
69	// created on screen in its "loading" state and no Cmd is executed. Each view
70	// migrated from a spinner.Model adds its seeds here, every one with the message
71	// that ends its load. The table is checked by TestActivityGuardFooterHasNoBraille
72	// and TestALoadingViewDrivesTheChain.
73	var footerLoadingSeeds = map[command.ViewType][]loadingSeed{
74		command.ViewStatus: {{"first check", seedStatusLoading,
75			func() tea.Msg { return uistatus.CheckCompleteMsg{Timestamp: time.Now()} }}},
76		command.ViewViewer: {{"document", seedViewerLoading,
77			func() tea.Msg { return uiviewer.DocumentLoadedMsg{Name: "notes.txt", Content: []byte("hello\n")} }}},
78		command.ViewOCIResources: {
79			{"images tab", seedOCIImagesLoading, func() tea.Msg { return ociresources.ImagesListMsg{} }},
80			{"networks tab", seedOCINetworksLoading, func() tea.Msg { return ociresources.NetworksListMsg{} }},
81			{"volumes tab", seedOCIVolumesLoading, func() tea.Msg { return ociresources.VolumesListMsg{} }},
82			{"tag search", seedOCITagSearch, ociTagSearchEnd},
83			{"network inspect", seedOCINetworkInspect, ociNetworkInspectEnd},
84		},
85	}
