87	// seedStatusLoading creates :status on screen with its first check unanswered.
88	func seedStatusLoading(t *testing.T, a *App) {
89		t.Helper()
90		delete(a.views, command.ViewStatus)
91		_ = a.switchView(command.ViewStatus) // its Init would run the checks: dropped
92		a.resize(a.width, a.height)
93	}
