95	// seedViewerLoading opens a file in the viewer; its Init Cmd is not run, so the
96	// document stays loading (DEVDESK-370).
97	func seedViewerLoading(t *testing.T, a *App) {
98		t.Helper()
99		a.Update(uiviewer.OpenRequestMsg{Source: viewer.NewFileSource("notes.txt")})
100		a.resize(a.width, a.height)
101	}
