103	// startRunning starts run, puts item in the running state and returns its id.
104	func startRunning(t *testing.T, a *App, run jobs.Run, item string) {
105		t.Helper()
106		a.Update(jobs.StartMsg{Run: run})
107		snap := a.jobs.Snapshot()
108		if len(snap) == 0 || !a.jobs.Advance(snap[len(snap)-1].ID, item, jobs.ItemRunning, "") {
109			t.Fatalf("the seed could not put %q in the running state: %+v", item, snap)
110		}
111		a.jobsChanged() // broadcast; the returned Cmd carries timers and is dropped
112	}
