196	// footerBrailleProblem is empty when footer holds no braille pattern character
197	// (U+2800 to U+28FF), the alphabet of the router's retired spinner frame.
198	func footerBrailleProblem(footer string) string {
199		for _, r := range ansi.Strip(footer) {
200			if r >= 0x2800 && r <= 0x28FF {
201				return fmt.Sprintf("the footer holds the braille frame %q: a migrated footer shows the activity dot", r)
202			}
203		}
204		return ""
205	}
206	
207	// forceRouterFrame hands the view on screen the router's "on" phase: a regression
208	// that still wrote a braille frame into a footer would show it here.
209	func forceRouterFrame(a *App, vt command.ViewType) {
210		a.anim.blinkOn = true
211		_ = a.sendFrameTo(vt)
212	}
213	
214	func viewFooter(t *testing.T, a *App, vt command.ViewType) string {
215		t.Helper()
216		fr, ok := a.views[vt].(footerRenderer)
217		if !ok {
218			t.Fatalf("view %q is a %T, which renders no footer", vt, a.views[vt])
219		}
220		return fr.RenderFooter(160)
221	}
222	
223	func TestActivityGuardFooterBrailleLogic(t *testing.T) {
224		if got := footerBrailleProblem("  1 job running"); got != "" {
225			t.Errorf("a clean footer: %s", got)
226		}
227		if got := footerBrailleProblem("  ⠹ 1 job running"); got == "" {
228			t.Error("a footer with a braille frame passed")
229		}
230		if got := footerBrailleProblem("  \x1b[31m⣿\x1b[0m x"); got == "" {
231			t.Error("a styled braille frame passed")
232		}
233		if got := footerBrailleProblem("  ● ○ ◴ ⊗ ◐ ◕ ◉ ⊘ ⊖ ◌ text"); got != "" {
234			t.Errorf("the activity alphabet is not braille: %s", got)
235		}
236	}
237	
238	// DEVDESK-341: no braille in a migrated footer, and the shared dot is there once.
239	func TestActivityGuardFooterHasNoBraille(t *testing.T) {
240		// Every key is a view the activity guard already classifies: a migrated
241		// table, or an exempt view with its documented reason (the dashboard).
242		for vt := range footerActivitySeeds {
243			if len(migratedTables[vt]) == 0 && exemptViews[vt] == "" {
244				t.Errorf("view %q has a footer-dot seed but is neither migrated (migratedTables) nor exempt with a reason (exemptViews)", vt)
245			}
246		}
247		run := indicator.Glyph(indicator.Running, true)
248		for vt, seed := range footerActivitySeeds {
249			t.Run(string(vt), func(t *testing.T) {
250				a := routerAt(t, &bareView{}, 180, 40)
251				seed(t, a)
252				if a.currentView != vt {
253					t.Fatalf("the seed left %q on screen, want %q", a.currentView, vt)
254				}
255				forceRouterFrame(a, vt)
256				footer := viewFooter(t, a, vt)
257				if msg := footerBrailleProblem(footer); msg != "" {
258					t.Errorf("view %q: %s\n%s", vt, msg, ansi.Strip(footer))
259				}
260				if n := strings.Count(ansi.Strip(footer), run); n != 1 {
261					t.Errorf("view %q: the footer holds %d running glyphs, want exactly 1\n%s", vt, n, ansi.Strip(footer))
262				}
263			})
264		}
265		// A loading view: phase on, then off, no braille, exactly one dot each time.
266		on, off := indicator.Glyph(indicator.Running, true), indicator.Glyph(indicator.Running, false)
267		for vt, seeds := range footerLoadingSeeds {
268			for _, ls := range seeds {
269				t.Run(fmt.Sprintf("loading/%s/%s", vt, ls.name), func(t *testing.T) {
270					a := routerAt(t, &bareView{}, 180, 40)
271					ls.seed(t, a)
272					if a.currentView != vt {
273						t.Fatalf("the seed left %q on screen, want %q", a.currentView, vt)
274					}
275					for _, phase := range []struct {
276						on         bool
277						want, then string
278					}{{true, on, off}, {false, off, on}} {
279						a.anim.blinkOn = phase.on
280						_ = a.sendFrameTo(vt)
281						footer := viewFooter(t, a, vt)
282						plain := ansi.Strip(footer)
283						if msg := footerBrailleProblem(footer); msg != "" {
284							t.Errorf("view %q: %s\n%s", vt, msg, plain)
285						}
286						if n := strings.Count(plain, phase.want); n != 1 || strings.Contains(plain, phase.then) {
287							t.Errorf("view %q, phase on=%v: want exactly one %s and no %s\n%s", vt, phase.on, phase.want, phase.then, plain)
288						}
289					}
290				})
291			}
292		}
293		// The views that keep a spinner of their own are out of scope while they load:
294		// the seeds below are loaded and selected on a busy row.
295		keys := make([]string, 0, len(migratedFooterSeeds))
296		for vt := range migratedFooterSeeds {
297			keys = append(keys, string(vt))
298		}
299		sort.Strings(keys)
300		for _, k := range keys {
301			vt := command.ViewType(k)
302			t.Run("row/"+k, func(t *testing.T) {
303				a := routerAt(t, &bareView{}, 180, 40)
304				migratedFooterSeeds[vt](t, a)
305				forceRouterFrame(a, vt)
306				if msg := footerBrailleProblem(viewFooter(t, a, vt)); msg != "" {
307					t.Errorf("view %q: %s", vt, msg)
308				}
309			})
310		}
311	}
312	
313	// footerFrameConsumers lists every package under internal/ui whose Update takes
314	// a jobs.FrameMsg, and what it does with it for the footer: the view whose seed
315	// in footerActivitySeeds proves the dot, or the reason the package is exempt.
316	// A package that starts handling jobs.FrameMsg fails the test below until it is
317	// written down here (DEVDESK-341, plan section 3).
318	var footerFrameConsumers = map[string]struct {
319		View   command.ViewType // set: the footer shows the dot, seeded in footerActivitySeeds
320		Exempt string           // set: why the footer keeps its own spinner or has none
321	}{
322		"ui/dashboard":      {View: command.ViewDashboard},
323		"ui/jobsview":       {View: command.ViewJobs},
324		"ui/workspaces":     {View: command.ViewWorkspaces},
325		"ui/templates":      {View: command.ViewTemplates},
326		"ui/security":       {View: command.ViewSecurity},
327		"ui/oci_resources":  {View: command.ViewOCIResources},
328		"ui/forge/explorer": {View: command.ViewGitExplorer},
329		"ui/status":         {View: command.ViewStatus},
330		"ui/viewer":         {View: command.ViewViewer},
331		"ui/netdiag":        {Exempt: "own spinner.Model feeds its Spinner status; the frame only drives table blink (plan 1.2)"},
332		"ui/containers":     {Exempt: "own spinner.Model feeds its Spinner status; the frame only drives table blink (plan 1.2)"},
333		"ui/agentusageview": {Exempt: "own spinner.Model feeds its Spinner status; the frame only drives table blink (plan 1.2)"},
334	}
335	
336	// footerFrameConsumerProblems compares the packages found handling a
337	// jobs.FrameMsg with the classification table.
338	func footerFrameConsumerProblems(found map[string]bool, table map[string]struct {
339		View   command.ViewType
340		Exempt string
341	}, seeds map[command.ViewType]footerSeed) []string {
342		var out []string
343		for dir := range found {
344			c, ok := table[dir]
345			switch {
346			case !ok:
347				out = append(out, fmt.Sprintf("%s handles jobs.FrameMsg but is in neither footerActivitySeeds nor an exemption (footerFrameConsumers)", dir))
348			case c.View != "" && c.Exempt != "":
349				out = append(out, fmt.Sprintf("%s is both seeded and exempt", dir))
350			case c.View == "" && c.Exempt == "":
351				out = append(out, fmt.Sprintf("%s is classified without a view or a reason", dir))
352			case c.View != "" && seeds[c.View] == nil:
353				out = append(out, fmt.Sprintf("%s names view %q, which has no footer seed", dir, c.View))
354			}
355		}
356		for dir := range table {
357			if !found[dir] {
358				out = append(out, fmt.Sprintf("footerFrameConsumers lists %s, which no longer handles jobs.FrameMsg: drop the entry", dir))
359			}
360		}
361		for vt := range seeds {
362			listed := false
363			for _, c := range table {
364				listed = listed || c.View == vt
365			}
366			if !listed {
367				out = append(out, fmt.Sprintf("footerActivitySeeds has view %q, which footerFrameConsumers does not map to a consumer", vt))
368			}
369		}
370		sort.Strings(out)
371		return out
372	}
373	
374	// frameConsumerSeeds is every view with a footer-dot seed: the jobs-driven ones
375	// and the ones that load on their own (footerLoadingSeeds, DEVDESK-369).
376	func frameConsumerSeeds() map[command.ViewType]footerSeed {
377		out := map[command.ViewType]footerSeed{}
378		for vt, seed := range footerActivitySeeds {
379			out[vt] = seed
380		}
381		for vt, seeds := range footerLoadingSeeds {
382			if len(seeds) > 0 {
383				out[vt] = seeds[0].seed
384			}
385		}
386		return out
387	}
388	
389	func TestActivityGuardFrameConsumersAreClassifiedLogic(t *testing.T) {
390		type entry = struct {
391			View   command.ViewType
392			Exempt string
393		}
394		seeds := map[command.ViewType]footerSeed{command.ViewDashboard: seedDashboardActivity}
395		good := map[string]entry{"ui/dashboard": {View: command.ViewDashboard}, "ui/x": {Exempt: "own spinner"}}
396		if p := footerFrameConsumerProblems(map[string]bool{"ui/dashboard": true, "ui/x": true}, good, seeds); len(p) != 0 {
397			t.Errorf("a classified set reported %v", p)
398		}
399		if p := footerFrameConsumerProblems(map[string]bool{"ui/dashboard": true, "ui/x": true, "ui/new": true}, good, seeds); len(p) != 1 {
400			t.Errorf("an unclassified consumer: %v", p)
401		}
402		if p := footerFrameConsumerProblems(map[string]bool{"ui/dashboard": true}, good, seeds); len(p) != 1 {
403			t.Errorf("a stale exemption: %v", p)
404		}
405		if p := footerFrameConsumerProblems(map[string]bool{"ui/dashboard": true, "ui/x": true}, map[string]entry{"ui/dashboard": {View: command.ViewDashboard}, "ui/x": {}}, seeds); len(p) != 1 {
406			t.Errorf("a consumer with neither view nor reason: %v", p)
407		}
408		if p := footerFrameConsumerProblems(map[string]bool{"ui/dashboard": true, "ui/x": true}, good, map[command.ViewType]footerSeed{command.ViewDashboard: seedDashboardActivity, command.ViewJobs: seedJobsActivity}); len(p) != 1 {
409			t.Errorf("a seed no consumer maps to: %v", p)
410		}
411	}
412	
413	func TestActivityGuardFrameConsumersAreClassified(t *testing.T) {
414		found := map[string]bool{}
415		sourceFiles(t, func(rel string, _ *token.FileSet, file *ast.File) {
416			if !strings.HasPrefix(rel, "ui/") {
417				return
418			}
419			ast.Inspect(file, func(n ast.Node) bool {
420				cc, ok := n.(*ast.CaseClause)
421				if !ok {
422					return true
423				}
424				for _, e := range cc.List {
425					if sel, ok := e.(*ast.SelectorExpr); ok && sel.Sel.Name == "FrameMsg" {
426						if x, ok := sel.X.(*ast.Ident); ok && x.Name == "jobs" {
427							found[filepath.ToSlash(filepath.Dir(rel))] = true
428						}
429					}
430				}
431				return true
432			})
433		})
434		if len(found) == 0 {
435			t.Fatal("no `case jobs.FrameMsg` found under internal/ui: the scan reads nothing")
436		}
437		for _, p := range footerFrameConsumerProblems(found, footerFrameConsumers, frameConsumerSeeds()) {
438			t.Error(p)
439		}
440	}
