442	// renderedFrameUses reports every identifier named RenderedFrame in file: a
443	// selector, a composite key, a field or a declaration.
444	func renderedFrameUses(fset *token.FileSet, file *ast.File) []finding {
445		var out []finding
446		ast.Inspect(file, func(n ast.Node) bool {
447			if id, ok := n.(*ast.Ident); ok && id.Name == renderedFrameName {
448				out = append(out, finding{Pos: fset.Position(id.Pos()), What: "reference to " + renderedFrameName})
449			}
